const fs=require('fs'),path=require('path'),crypto=require('crypto'),sharp=require('sharp');
const root=path.resolve(__dirname,'..'),base=path.join(root,'marketing/assets/figma-global-collection-20261010'),out=path.join(root,'marketing/assets/figma-global-sample-release-20261010');fs.mkdirSync(out,{recursive:true});
const choices=[['docker',7,'horizontal','컬러 가로조합형'],['dropbox',24,'symbol','블루 심볼'],['fastify',80,'horizontal','워드마크+심볼 가로형'],['firefox',89,'symbol','컬러 심볼'],['figma',87,'symbol','컬러 심볼'],['envoy',53,'horizontal','컬러 가로조합형'],['gitlab',142,'symbol','다색 심볼'],['gmail',171,'symbol','다색 심볼']];
(async()=>{const cms=JSON.parse(fs.readFileSync(path.join(base,'cms-current-variants.json'),'utf8'));let release={patches:{},variants:{}},uploads=[];
for(const [id,index,form,label] of choices){const name=`item-${String(index).padStart(4,'0')}`,dir=path.join(base,'items',name),raw=fs.readFileSync(path.join(dir,'logo.svg'));const png=await sharp(raw,{density:600,limitInputPixels:100000000}).resize({width:2000,height:2000,fit:'inside'}).png().toBuffer(),preview=fs.readFileSync(path.join(dir,'preview.png'));let files={};
for(const [filename,body] of [['logo.svg',raw],['logo.png',png],['preview.png',preview]]){const sha=crypto.createHash('sha256').update(body).digest('hex'),rel=`sources/community-global-20261010/${sha.slice(0,16)}/${filename}`,local=path.join(out,id,rel);fs.mkdirSync(path.dirname(local),{recursive:true});fs.writeFileSync(local,body);uploads.push({id,file:path.relative(root,local),key:`_clients/${id}/${rel}`,sha256:sha});files[filename]=rel;}
const cdn=JSON.parse(fs.readFileSync(path.join(base,'existing-variants',id+'.json'),'utf8')),prior=cms.find(x=>x.brand_id===id)?.asset_manifest?.variants;let manifest={...cdn,...prior,id,variants:[...(cdn.variants||[])]};for(const v of prior?.variants||[]){const existing=manifest.variants.findIndex(x=>x.key===v.key);if(existing>=0)manifest.variants[existing]=v;else manifest.variants.push(v);}const key=`community-global-${name}`;manifest.variants.push({key,form,color:'original',label:`${label} · 커뮤니티 수록`,files:{svg:files['logo.svg'],png:files['logo.png']},preview_png:files['preview.png'],provider:'사용자 제공 Figma Community SVG',origin:'collected',source_note:'1,400 SVG Logos Collection (Community) 내보내기에서 추출; 공식 원본 아님',source_sha256:'ab9166537a2f085477c1c83c03cc05d00ef5811161483ec7b36e7abf084c84b1',source_item:name,review_status:'verified',order:100});release.variants[id]=manifest;release.patches[id]={variants_n:manifest.variants.length};console.log('Prepared',id);}
fs.writeFileSync(path.join(out,'release.json'),JSON.stringify(release,null,2));fs.writeFileSync(path.join(out,'uploads.json'),JSON.stringify(uploads,null,2));for(const f of ['comparison-initial.jpg','comparison-second.jpg'])fs.copyFileSync(path.join(base,f),path.join(out,f));fs.writeFileSync(path.join(out,'README.md'),'8 visually reviewed additional variants. Existing CDN and current CMS variants merged; representatives/primary preserved. User-provided community collection, not official source. 640px preview + 2000px PNG + extracted SVG; 24 immutable objects. Duplicate artwork excluded. Root owns publication.\n');console.log('READY',Object.keys(release.variants).length,uploads.length);})().catch(e=>{console.error(e);process.exitCode=1;});
